const crypto = require('crypto');

function getVar(name) {
  try {
    if (typeof $vars !== 'undefined' && $vars[name]) return $vars[name];
  } catch {}
  try {
    if (typeof $env !== 'undefined' && $env[name]) return $env[name];
  } catch {}
  return '';
}

const secret = getVar('N8N_WEBHOOK_SECRET');
if (!secret) {
  throw new Error('N8N_WEBHOOK_SECRET variable is not configured in n8n.');
}

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const headers = item.json.headers || {};
  const sigHeader = headers['x-lendloop-signature'] || headers['X-LendLoop-Signature'] || '';

  // Read exact raw bytes captured by Webhook (rawBody: true)
  let rawBody = '';
  if (item.binary && item.binary.data) {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    rawBody = buf.toString('utf8');
  } else if (item.json.body !== undefined) {
    rawBody = typeof item.json.body === 'string'
      ? item.json.body
      : JSON.stringify(item.json.body);
  }

  let payload = {};
  try {
    payload = rawBody ? JSON.parse(rawBody) : (item.json.body || {});
  } catch {
    payload = item.json.body || {};
  }

  let timestamp = null;
  let signature = null;
  for (const part of String(sigHeader).split(',')) {
    const [k, v] = part.trim().split('=');
    if (k === 't') timestamp = parseInt(v, 10);
    if (k === 'v1') signature = v;
  }

  let isValid = false;
  let reason = '';

  if (!timestamp || Number.isNaN(timestamp) || !signature) {
    reason = 'Missing or malformed X-LendLoop-Signature header';
  } else if (Math.abs(Date.now() - timestamp) > 5 * 60 * 1000) {
    reason = 'Signature timestamp expired';
  } else {
    const expected = crypto
      .createHmac('sha256', secret)
      .update(`${timestamp}.${rawBody}`)
      .digest('hex');

    const a = Buffer.from(expected, 'utf8');
    const b = Buffer.from(signature, 'utf8');
    if (a.length === b.length && crypto.timingSafeEqual(a, b)) {
      isValid = true;
    } else {
      reason = 'HMAC signature mismatch';
    }
  }

  results.push({
    json: {
      isValid,
      reason,
      payload,
    },
  });
}

return results;

const crypto = require('crypto');

function getVar(name) {
  try {
    if (typeof $vars !== 'undefined' && $vars[name]) return $vars[name];
  } catch {}
  try {
    if (typeof $env !== 'undefined' && $env[name]) return $env[name];
  } catch {}
  return '';
}

const secret = getVar('N8N_WEBHOOK_SECRET');
const convexSiteUrl = getVar('CONVEX_SITE_URL').replace(/\/+$/, '');

if (!secret || !convexSiteUrl) {
  throw new Error('Missing N8N_WEBHOOK_SECRET or CONVEX_SITE_URL variable in n8n.');
}

const fmtDate = (ms) => new Date(ms).toLocaleDateString('en-US', {
  month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC'
});

const output = [];

for (const item of $input.all()) {
  const p = item.json.payload || {};
  const event = p.event;
  const toolName = p.tool?.name || 'Tool';
  const recipientName = p.recipient?.name || 'Neighbor';
  const recipientEmail = p.recipient?.email || '';
  const actorName = p.actor?.name || 'Neighbor';
  const loanId = p.loan?.id;
  const windowText = p.loan?.startDate && p.loan?.endDate
    ? `${fmtDate(p.loan.startDate)} – ${fmtDate(p.loan.endDate)}`
    : '';

  let subject = '';
  let message = '';
  let summary = '';

  switch (event) {
    case 'request.created':
      subject = `New LendLoop request for ${toolName}`;
      message = `Hi ${recipientName}, ${actorName} requested to borrow your ${toolName} (${windowText}). Open LendLoop to approve or decline.`;
      summary = `New borrow request notification delivered to ${recipientEmail}`;
      break;
    case 'request.approved':
      subject = `Approved: You can borrow ${toolName}`;
      message = `Good news ${recipientName}! ${actorName} approved your request for ${toolName} (${windowText}).`;
      summary = `Approval notification delivered to ${recipientEmail}`;
      break;
    case 'request.declined':
      subject = `Update on your ${toolName} request`;
      message = `Hi ${recipientName}, your borrow request for ${toolName} (${windowText}) was declined by ${actorName}.`;
      summary = `Decline notification delivered to ${recipientEmail}`;
      break;
    case 'loan.returned':
      subject = `Returned: ${toolName}`;
      message = `Hi ${recipientName}, ${toolName} has been marked as returned by ${actorName}. Thanks for sharing with the neighborhood!`;
      summary = `Return confirmation delivered to ${recipientEmail}`;
      break;
    default:
      subject = `LendLoop update for ${toolName}`;
      message = `Hi ${recipientName}, status update (${event}) for ${toolName}.`;
      summary = `Notification (${event}) delivered to ${recipientEmail}`;
  }

  const writebackBody = {
    loanId,
    workflow: 'request_notification',
    event,
    status: 'delivered',
    recipientEmail,
    summary,
    idempotencyKey: `${p.idempotencyKey || `${event}:${loanId}:${Date.now()}`}:delivered`,
  };

  const rawWritebackBody = JSON.stringify(writebackBody);
  const ts = Date.now();
  const sigHex = crypto
    .createHmac('sha256', secret)
    .update(`${ts}.${rawWritebackBody}`)
    .digest('hex');

  output.push({
    json: {
      notification: {
        to: recipientEmail,
        recipientName,
        subject,
        message,
        event,
      },
      convexSiteUrl,
      rawWritebackBody,
      writebackSignature: `t=${ts},v1=${sigHex}`,
    },
  });
}

return output;

// Logged mock notification channel (swap/connect Email, Slack, or Discord here using n8n credentials)
for (const item of $input.all()) {
  const n = item.json.notification;
  console.log('[LendLoop Notification Sent]', JSON.stringify({
    to: n.to,
    subject: n.subject,
    message: n.message,
    event: n.event,
    sentAt: new Date().toISOString(),
  }));
}
return $input.all();
